from common import p,step,svg,text,line,graph
import math

def curved(x1,y1,cx,cy,x2,y2):
    dx,dy=x2-cx,y2-cy
    d=math.hypot(dx,dy);dx/=d;dy/=d
    return f'<path d="M{x1} {y1} Q{cx} {cy} {x2} {y2}" fill="none" stroke="#a45423" stroke-width="2.5"/>'+f'<polygon points="{x2},{y2} {x2-10*dx+4*dy},{y2-10*dy-4*dx} {x2-10*dx-4*dy},{y2-10*dy+4*dx}" fill="#a45423"/>'

def lone(x,y,vertical=False):
    return f'<circle cx="{x-4 if not vertical else x}" cy="{y-4 if vertical else y}" r="2" fill="#233442"/><circle cx="{x+4 if not vertical else x}" cy="{y+4 if vertical else y}" r="2" fill="#233442"/>'

