def stereo_picture():
    body=text(400,25,'Inversion at the reacting carbon',19)
    for x,left,right in [(180,'Br','H'),(600,'Nu','H')]:
        body+=text(x,179,'C',25)+line(x-12,152,x-55,100)+text(x-68,88,'CH₃',22)
        body+=line(x+12,152,x+55,100)+text(x+80,88,'CH₂CH₃',22)
        a=(x,180);leftend=(x-70,255);rightend=(x+70,255)
        solid=leftend if x==180 else rightend
        hashed=rightend if x==180 else leftend
        body+=f'<polygon points="{a[0]},{a[1]} {solid[0]-7},{solid[1]} {solid[0]+7},{solid[1]}" fill="#31556b"/>'
        for j in range(1,8):
            t=j/8;xx=a[0]+t*(hashed[0]-a[0]);yy=a[1]+t*(hashed[1]-a[1])
            body+=line(xx-6*t,yy,xx+6*t,yy,width=1.5)
        body+=text(x-80,282,left,23)+text(x+80,282,right,23)
    body+=line(330,172,450,172,arrow=True)+text(390,150,'SN2',18)
    body+=text(400,328,'The spatial arrangement inverts; optical-rotation sign is not inferred.',16)
    return svg(body,800,365)

def benzene_picture():
    def ring(cx,cy,aromatic=True,intermediate=False):
        coords=[(cx,cy-60),(cx+52,cy-30),(cx+52,cy+30),(cx,cy+60),(cx-52,cy+30),(cx-52,cy-30)]
        out=''
        for j in range(6):out+=line(*coords[j],*coords[(j+1)%6])
        double_edges=[0,2,4] if not intermediate else [2,4]
        for j in double_edges:
            a,c=coords[j],coords[(j+1)%6]
            out+=line(cx+(a[0]-cx)*.80,cy+(a[1]-cy)*.80,cx+(c[0]-cx)*.80,cy+(c[1]-cy)*.80)
        return out
    body=text(400,24,'Electrophilic substitution of benzene',19)
    body+=ring(130,180)+text(130,65,'E⁺',25)+curved(155,143,195,70,141,73)
    body+=line(215,180,285,180,arrow=True)
    body+=ring(390,180,intermediate=True)+line(390,120,390,80)+text(390,64,'E',23)
    body+=line(390,120,428,91)+text(446,84,'H',23)+text(460,151,'+',23)
    body+=text(515,65,'B',23)+lone(495,57,True)+curved(495,57,471,52,450,72)
    body+=curved(410,105,456,110,426,143)
    body+=line(480,180,555,180,arrow=True)
    body+=ring(660,180)+line(660,120,660,80)+text(660,64,'E',23)+text(660,290,'+ BH⁺',22)
    body+=text(400,335,'Ring attack; then loss of H⁺ restores the delocalized system.',16)
    return svg(body,800,370)

